class Solution {
public:
    int findLeastNumOfUniqueInts(vector<int>& arr, int k) {
        int n = (int)arr.size();
        unordered_map<int,int> freq;
        freq.reserve(n * 2);
        for (int x : arr) freq[x]++;
        vector<int> bucket(n + 1, 0);
        for (auto& p : freq) bucket[p.second]++;
        int unique = (int)freq.size();
        for (int f = 1; f <= n; f++) {
            if (bucket[f] == 0) continue;
            long long cost = (long long)f * (long long)bucket[f];
            if (cost <= (long long)k) {
                k -= (int)cost;
                unique -= bucket[f];
            } else {
                break;
            }
        }
        return unique;
    }
};
